#nullable enable // autogenerated

using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace MVZ2.Sprites
{
    [CreateAssetMenu(fileName = "NewGeneratedSpriteManifest", menuName = "MVZ2/Generated Sprite Manifest")]
    public class GeneratedResourceManifest : ScriptableObject
    {
        public void Reset()
        {
            textures.Clear();
            categories.Clear();
            audioClips.Clear();
        }
        public void Clear()
        {
            foreach (var category in categories)
            {
                foreach (var sprite in category.sprites)
                {
                    Destroy(sprite.sprite);
                }
                category.sprites.Clear();
            }
            foreach (var texture in textures)
            {
                Destroy(texture.texture);
            }
            foreach (var audioClip in audioClips)
            {
                Destroy(audioClip.clip);
            }
            Reset();
        }
        public void AddTexture2D(Texture2D texture2D)
        {
            textures.Add(new GeneratedTexture2D(texture2D));
        }
        public bool RemoveTexture2D(Texture2D texture2D)
        {
            var generated = textures.FindIndex(g => g.texture == texture2D);
            if (generated < 0)
                return false;
            textures.RemoveAt(generated);
            return true;
        }
        public void AddAudioClip(AudioClip audioClip)
        {
            audioClips.Add(new GeneratedAudioClip(audioClip));
        }
        public bool RemoveAudioClip(AudioClip audioClip)
        {
            var generated = audioClips.FindIndex(g => g.clip == audioClip);
            if (generated < 0)
                return false;
            audioClips.RemoveAt(generated);
            return true;
        }
        public void AddSprite(string category, Sprite sprite, Sprite background)
        {
            var cat = categories.FirstOrDefault(c => c.name == category);
            if (cat == null)
            {
                cat = new GeneratedSpriteCategory(category);
                categories.Add(cat);
            }
            cat.AddSprite(sprite, background);
        }
        public void RemoveSprite(string category, string name)
        {
            var cat = categories.FirstOrDefault(c => c.name == category);
            if (cat == null)
                return;
            cat.RemoveSprite(name);
            if (cat.Count <= 0)
            {
                categories.Remove(cat);
            }
        }
        public List<GeneratedTexture2D> textures = new List<GeneratedTexture2D>();
        public List<GeneratedSpriteCategory> categories = new List<GeneratedSpriteCategory>();
        public List<GeneratedAudioClip> audioClips = new List<GeneratedAudioClip>();
    }
}
